pyq_focus = [
 "Unit 2 (Poetry) se NET mein har paper mein 8-12 sawaal aate hain, isliye yeh sabse scoring unit hai.",
 "Sabse zyada poochha jata hai: poem kis poet ki hai, famous line kis poem ki hai, aur collection kis saal chhapa.",
 "Chronology wale sawaal (Milton, Pope, Romantic, Victorian, Yeats ke collections) almost har saal aate hain - saal yaad karo, kam se kam decade.",
 "Match-the-following mein poet-poem, poem-character (Belinda, Achitophel, Sporus, Satan, Duke of Ferrara) aur stanza-poem jodne ko kehte hain.",
 "Prosody aur forms bhi pakke hain: sonnet types, ottava rima, terza rima, Spenserian stanza, villanelle, sprung rhythm, metrical feet.",
 "Romantic poets (Wordsworth ka Preface, Keats ki letters, Shelley ka Defence) aur Eliot-Yeats-Pound ka modern poetry sabse heavy area hai.",
 "Indian English (Ezekiel, Ramanujan, Kamala Das, Kolatkar, Mahapatra) aur postcolonial (Walcott, Soyinka, Brathwaite) se 2018 ke baad zyada sawaal aaye hain.",
 "Assertion-Reason mein dhyan do: dono sahi hon to bhi check karo ki R sach mein A ko explain karta hai ya nahi.",
 "Taiyari ka tareeka: har din ek age padho, phir isi file ke works, quotes aur people ko flashcard ki tarah revise karo, aur MCQs do baar lagao."
]

easy = [
 {"title":"Old English Poetry (c. 450-1066)",
  "story":"Bahut purane zamane mein England mein log aag ke paas baith kar veer yoddhaon ki kahaniyan gaate the, jaise hamare gaon mein Alha-Udal gaaye jaate hain. Sabse badi kahani Beowulf hai - ek hero jo Grendel naam ke rakshas, uski maa aur aakhir mein ek dragon se ladta hai. Is kavita mein rhyme nahi hoti, ek hi aawaz se shuru hone wale shabd (alliteration) baar baar aate hain. Samudra ko 'whale-road' kehte the - isko kenning kehte hain. Caedmon's Hymn sabse purani English kavita hai jo Bede ne likh kar bachayi.",
  "trick":"'Bade Gande Dragon' = Beowulf ne Grendel, (Grendel ki maa) aur Dragon ko mara; aur 'C se Caedmon, C se sabse Pehla' yaad rakho."},
 {"title":"Middle English Poetry (1066-c. 1500, excluding Chaucer)",
  "story":"1066 mein Normans aaye aur French bolne lage, to English thodi badal gayi - jaise Hindi mein Angrezi shabd ghus gaye. Is daur mein bahadur knights ki kahaniyan (romance) chalti thi. Sir Gawain and the Green Knight mein ek hara aadmi kehta hai 'meri gardan kaato, ek saal baad main tumhari kaatunga'. Langland ki Piers Plowman ek sapne ki kahani hai jisme garib kisaan sabse achha insaan hai. Gower ne Confessio Amantis likhi.",
  "trick":"'Green Gawain, Sapna Langland, Gower ka Confession' - Gawain hara, Langland sapne mein, Gower confession karta hai."},
 {"title":"Geoffrey Chaucer (c. 1343-1400)",
  "story":"Chaucer ko English poetry ka 'baap' kehte hain (Dryden ne yeh kaha). Socho ek bus mein alag alag log tirth yatra par ja rahe hain - knight, miller, Wife of Bath, Pardoner - aur time pass ke liye har koi ek kahani sunata hai. Yahi The Canterbury Tales hai. Host Harry Bailly kehta hai jiski kahani sabse achhi hogi use free khana milega. Troilus and Criseyde ek dukhi prem kahani hai jo rhyme royal mein hai.",
  "trick":"'CT = Canterbury Tales = Chalti Train ki kahaniyan'; 'RR = Rhyme Royal = Raja ka ababbcc'."},
 {"title":"Renaissance and Elizabethan Poetry",
  "story":"Renaissance matlab nayi roshni - Italy se sonnet England aaya, jaise bahar se naya fashion aata hai. Wyatt aur Surrey sonnet laye, aur Surrey ne blank verse (bina rhyme ki pentameter) shuru ki. Spenser ne The Faerie Queene likhi jisme har knight ek guna (virtue) hai. Sidney ne Astrophil and Stella sonnets likhe aur Shakespeare ne 154 sonnets. Marlowe ne 'Come live with me and be my love' likha.",
  "trick":"'Wyatt-Surrey Sonnet laaye, Surrey ne Sur bina rhyme ka (blank verse)'; Shakespeare ke sonnet = 154 = 'ek sau chauvan, ladki-ladka dono ke naam'."},
 {"title":"Metaphysical and Cavalier Poets",
  "story":"Metaphysical poet ajeeb, dimaagi tulna karte the - Donne kehta hai do premi compass ke do pairon jaise hain, ek ghoomta hai to doosra bhi jhukta hai. Isko conceit kehte hain. Dr Johnson ne inka naam 'metaphysical poets' rakha. Herbert, Vaughan, Crashaw dharmik kavitayein likhte the. Cavalier poets (Herrick, Lovelace) raja ke saathi the aur halki-phulki prem kavitayein likhte the: 'Gather ye rosebuds while ye may' - jab tak jawani hai maze karo.",
  "trick":"'Donne ka Dimaag, Herrick ki Hasi' - Metaphysical = dimaag wale conceit, Cavalier = masti wale gaane."},
 {"title":"John Milton (1608-1674)",
  "story":"Milton andha ho gaya tha phir bhi usne sahayakon ko bol kar Paradise Lost likhwayi. Yeh Adam-Eve ke swarg se nikaale jaane ki kahani hai, aur Satan ka character itna dumdaar hai ki log use hi hero samajh lete hain. Pehle edition mein 10 books thi, baad mein 12. Lycidas uske dost Edward King ke doobne par likha shok-geet hai. Samson Agonistes mein andha Samson hai - bilkul Milton jaisa.",
  "trick":"'Comus-Lycidas-Lost-Samson' = 'Kal Lado, Lo Saza' (1634, 1637, 1667, 1671) - order yaad rahega."},
 {"title":"Neoclassical (Restoration and Augustan) and Transitional Poetry",
  "story":"Is daur mein kavita bahut niyam se chalti thi, jaise school ki uniform - har do line rhyme karti thi (heroic couplet). Dryden aur Pope ne logon ka mazaak udane wali kavita (satire) likhi. Pope ki The Rape of the Lock mein ek ladki Belinda ke baalon ki lat kaatne ko itna bada bana diya jaise koi mahayuddh ho - yeh mock-epic hai. Baad mein Gray, Collins, Cowper aaye jinmein prakriti aur dukh wapas aane laga - inhe transitional ya pre-Romantic kehte hain.",
  "trick":"'Dryden-Pope = Dono Pakke Couplet wale'; 'Baal ki lat = Belinda ki lat = Rape of the Lock'."},
 {"title":"Romantic Poetry I: Blake, Wordsworth, Coleridge",
  "story":"1798 mein Wordsworth aur Coleridge ne Lyrical Ballads chhapi aur kaha - kavita aam aadmi ki bhasha mein, gaon aur prakriti ke baare mein ho. Wordsworth ko daffodils aur pahad pasand the, Coleridge ko jaadu aur rahasya, jaise Ancient Mariner jo albatross maar kar musibat mein padta hai. Blake ne bachpan ki masoomiyat (Innocence) aur duniya ki kadwahat (Experience) ke geet likhe - Lamb aur Tyger. Yeh sab feelings ko sabse upar rakhte the.",
  "trick":"'1798 = Lyrical Ballads = Romantic ka janamdin'; Blake = 'Lamb masoom, Tyger khatarnak'."},
 {"title":"Romantic Poetry II: Byron, Shelley, Keats",
  "story":"Yeh teeno jawani mein hi chal base - jaise teen tez tare jo jaldi bujh gaye. Byron bagawati aur mazakiya tha, Don Juan aur Childe Harold likhe. Shelley krantikaari tha - 'If Winter comes, can Spring be far behind?' Keats sundarta ka pujari tha aur 1819 mein usne mahaan odes likhe; 25 saal mein TB se mar gaya. Shelley ne Keats ki maut par Adonais likha.",
  "trick":"'BSK = Bada Sundar Kavi': Byron 1824, Shelley 1822, Keats 1821 mein mare - ulta order: K-S-B."},
 {"title":"Victorian Poetry",
  "story":"Queen Victoria ke raaj mein science aur dharm ki ladai chal rahi thi, isliye kavita mein shak aur chinta aayi. Tennyson ne dost Hallam ki maut par In Memoriam likha. Browning ne dramatic monologue ko mashhoor kiya - My Last Duchess mein Duke apni maari hui biwi ki tasveer dikha raha hai. Arnold ki Dover Beach mein vishwas ka samundar peechhe hat raha hai. Hopkins ne sprung rhythm banaya.",
  "trick":"'TBA = Tennyson-Browning-Arnold = Victorian ki Top Bench Army'; Browning = 'Bolta akela, sunta chupchaap' (dramatic monologue)."},
 {"title":"Modern Poetry (1900-1939): Yeats, Eliot, Pound, Imagism, War Poets",
  "story":"Pehle vishwa yuddh ke baad duniya toot-phoot gayi, aur kavita bhi tukdon mein likhi jane lagi. Eliot ki The Waste Land ek toota hua shehar hai jahan April sabse kroor mahina hai. Pound ne kaha 'Make it new' aur Imagism mein chhoti, saaf tasveer jaisi kavita likhi. Yeats Irish poet tha jisne kaha 'Things fall apart'. Owen jaise sainik kaviyon ne yuddh ki sachchai dikhayi.",
  "trick":"'YEP = Yeats, Eliot, Pound - Modern ke teen YEP!'; Nobel: Yeats 1923, Eliot 1948 - '23 ka jawan, 48 ka budhaa'."},
 {"title":"Thirties and Post-War British Poetry",
  "story":"1930s mein Auden aur uske dost (Spender, MacNeice, Day-Lewis) politics aur samaj par likhte the - jaise college ke left-wing dost. Dylan Thomas bahut bhaavuk aur sangeetmay tha - 'Do not go gentle into that good night' apne bimaar pita ke liye. 1950s mein Movement ke poet (Larkin) bilkul seedhi, aam zindagi ki baat karte the. Ted Hughes janwaron ki taaqat aur Heaney Ireland ki mitti ke baare mein likhte the.",
  "trick":"'Auden ka Group, Larkin ka Movement, Heaney ka Digging' - teen daur teen naam."},
 {"title":"American Poetry",
  "story":"America ki kavita ne apni alag pehchaan banayi. Whitman ne free verse mein poore desh ko gale lagaya - 'I celebrate myself'. Emily Dickinson ghar mein band rehkar chhoti chhoti dash wali kavitayein likhti rahi. Frost gaon ke raaston aur deewaron ki baat karta hai. Baad mein Ginsberg ke Beat poets aur Plath, Lowell jaise confessional poets ne apne dard ko khul kar likha.",
  "trick":"'Whitman = Wide (khula free verse), Dickinson = Dash, Frost = Farm' - teen W-D-F."},
 {"title":"Indian English Poetry",
  "story":"Angrezon ke zamane mein Indian logon ne bhi English mein kavita shuru ki. Derozio pehle bade kavi the, Toru Dutt ne Our Casuarina Tree likha, aur Sarojini Naidu 'Nightingale of India' kehlayin. Tagore ko Gitanjali par 1913 mein Nobel mila. Azaadi ke baad Nissim Ezekiel ne modern Indian English poetry shuru ki - Night of the Scorpion mein maa ko bichhu kaat leta hai. Kamala Das, Ramanujan aur Kolatkar (Jejuri) bhi zaroori hain.",
  "trick":"'DTS-TE' = Derozio, Toru, Sarojini, Tagore, Ezekiel - purane se naye tak; Ezekiel ka bichhu, Kolatkar ka mandir (Jejuri)."},
 {"title":"Postcolonial and Commonwealth Poetry",
  "story":"Jin deshon par angrezon ka raaj tha - Caribbean, Africa, Australia - wahan ke kaviyon ne English mein apni kahani boli, jaise koi ghar ki boli mein sasural ki shikayat kare. Walcott (St Lucia) ne Omeros mein Homer ki kahani Caribbean machhuaron par likhi aur 1992 mein Nobel jeeta. Soyinka ki Telephone Conversation mein ek angrez makaan-malkin rang poochhti hai. Brathwaite ne 'nation language' ki baat ki. Okot p'Bitek ki Lawino apne pati Ocol ke angrezi tareekon par taane maarti hai.",
  "trick":"'Walcott = Waves (Caribbean samundar), Soyinka = Sound (telephone), Lawino = Lady ki shikayat'."},
 {"title":"Prosody and Metre",
  "story":"Kavita ki chaal ko metre kehte hain, jaise dil ki dhadkan 'da-DUM da-DUM'. Ek kamzor aur ek zor wala syllable mile to iamb banta hai, ulta ho to trochee. Paanch iamb ek line mein = iambic pentameter, jo English ki sabse common line hai. Bina rhyme ki iambic pentameter ko blank verse kehte hain. Line ke beech ka ruk-na caesura hai, aur line ka agli line mein beh jana enjambment.",
  "trick":"'Iamb = i-AM (main hoon), Trochee = TRO-chee (pehle zor)'; 'Anapaest = 2 chhote 1 bada, Dactyl = ungli jaisa: 1 bada 2 chhote'."},
 {"title":"Poetic Forms, Stanzas and Genres",
  "story":"Kavita ke alag alag dibbe hote hain, jaise tiffin ke khane. Sonnet 14 line ka dibba hai, villanelle 19 line ka jisme do lines baar baar aati hain. Ode kisi cheez ki tareef ka lamba geet hai, elegy maut par shok-geet. Ottava rima mein 8 line (abababcc), terza rima mein teen-teen line ki zanjeer. Mock-epic chhoti baat ko mahakavya jaisa bada bana deta hai.",
  "trick":"'14 Sonnet, 19 Villanelle, 39 Sestina' - 'Ek Chaar, Ek Nau, Teen Nau'; 'Ottava = Octo = 8'."},
]
